<template>
  <AuthenticatedLayout page-title="Solicitações de Despesa">
    <div class="space-y-6">
      <TopCard title="Solicitações de Despesa" :icon="ReceiptIcon"><template #actions><div class="flex gap-2"><NeonButton variant="secondary" @click="openRules">Regras de aprovação</NeonButton><NeonButton @click="openCreate">Nova solicitação</NeonButton></div></template></TopCard>
      <div v-if="error" class="rounded-lg border border-red-500/40 bg-red-500/10 p-4 text-red-100">{{ error }}</div>
      <div class="grid gap-4 lg:grid-cols-2"><article v-for="item in requests" :key="item.id" class="rounded-lg border border-gray-700 bg-gray-900/70 p-5"><div class="flex justify-between gap-3"><div><p class="font-semibold text-white">{{ item.title || item.description }}</p><p class="mt-1 text-sm text-gray-400">Vencimento: {{ item.due_date }}</p></div><span class="rounded-full bg-cyan-500/10 px-3 py-1 text-xs font-semibold text-cyan-200">{{ status(item.status) }}</span></div><p class="mt-4 text-2xl font-semibold text-white">{{ money(item.amount) }}</p><p class="mt-2 text-sm text-gray-400">{{ item.description }}</p><div v-if="item.approvals?.length" class="mt-4 border-t border-gray-800 pt-3 text-sm"><p v-for="approval in item.approvals" :key="approval.id" class="text-gray-300">{{ approval.approver?.name }}: {{ approval.decision === 'approved' ? 'Aprovou' : 'Recusou' }} - {{ approval.justification }}</p></div><div class="mt-5 flex flex-wrap gap-2"><NeonButton v-if="canSubmit(item)" size="sm" @click="submit(item)">Enviar</NeonButton><NeonButton v-if="item.status === 'in_approval'" size="sm" variant="secondary" @click="openDecision(item, 'approved')">Aprovar</NeonButton><NeonButton v-if="item.status === 'in_approval'" size="sm" variant="danger" @click="openDecision(item, 'rejected')">Recusar</NeonButton><NeonButton v-if="item.status === 'approved'" size="sm" variant="success" @click="convert(item)">Criar despesa</NeonButton><span v-if="item.status === 'converted'" class="text-sm text-emerald-300">Despesa criada</span></div></article></div>
      <div v-if="!requests.length && !loading" class="rounded-lg border border-gray-700 bg-gray-900/60 py-16 text-center text-gray-400">Nenhuma solicitação encontrada.</div>
    </div>
    <div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"><form class="w-full max-w-xl rounded-lg border border-cyan-500/30 bg-gray-900 p-6" @submit.prevent="save"><h2 class="text-xl font-semibold text-white">Nova solicitação</h2><div class="mt-4 grid gap-4"><input v-model="form.title" class="input" placeholder="Título" required><textarea v-model="form.description" class="input min-h-24" placeholder="Justificativa e detalhes"/><div class="grid grid-cols-2 gap-3"><input v-model.number="form.amount" class="input" type="number" min="0.01" step="0.01" placeholder="Valor" required><input v-model="form.due_date" class="input" type="date" required></div></div><div class="mt-6 flex justify-end gap-2"><NeonButton type="button" variant="secondary" @click="modal = false">Cancelar</NeonButton><NeonButton type="submit" :is-loading="saving">Salvar rascunho</NeonButton></div></form></div>
    <div v-if="decisionModal" class="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"><form class="w-full max-w-lg rounded-lg border border-cyan-500/30 bg-gray-900 p-6" @submit.prevent="decide"><h2 class="text-xl font-semibold text-white">{{ decision === 'approved' ? 'Aprovar' : 'Recusar' }} solicitação</h2><textarea v-model="justification" class="input mt-4 min-h-28" placeholder="Justificativa obrigatória" required/><div class="mt-6 flex justify-end gap-2"><NeonButton type="button" variant="secondary" @click="decisionModal = false">Cancelar</NeonButton><NeonButton type="submit">Confirmar</NeonButton></div></form></div>
    <div v-if="rulesModal" class="fixed inset-0 z-50 overflow-y-auto bg-black/70 p-4"><section class="mx-auto my-8 w-full max-w-2xl rounded-lg border border-cyan-500/30 bg-gray-900 p-6"><div class="flex items-center justify-between"><h2 class="text-xl font-semibold text-white">Regras de aprovação</h2><button class="text-gray-400" @click="rulesModal = false">Fechar</button></div><p class="mt-2 text-sm text-gray-400">As etapas são aplicadas em ordem para a faixa de valor configurada.</p><div class="mt-4 space-y-2"><div v-for="rule in rules" :key="rule.id" class="flex items-center justify-between rounded border border-gray-700 p-3 text-sm text-gray-200"><span>Etapa {{ rule.approval_order }}: {{ rule.profile?.name || rule.user?.name }} | {{ money(rule.minimum_amount) }} a {{ rule.maximum_amount ? money(rule.maximum_amount) : 'sem limite' }}</span><button class="text-red-300" @click="removeRule(rule)">Remover</button></div></div><form class="mt-5 grid gap-3 rounded border border-gray-700 p-4 md:grid-cols-2" @submit.prevent="saveRule"><select v-model="ruleForm.profile_id" class="input" required><option value="">Perfil aprovador</option><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{ profile.name }}</option></select><input v-model.number="ruleForm.approval_order" class="input" type="number" min="1" placeholder="Ordem" required><input v-model.number="ruleForm.minimum_amount" class="input" type="number" min="0" step="0.01" placeholder="Valor mínimo" required><input v-model.number="ruleForm.maximum_amount" class="input" type="number" min="0" step="0.01" placeholder="Valor máximo (opcional)"><div class="md:col-span-2 flex justify-end"><NeonButton type="submit">Adicionar regra</NeonButton></div></form></section></div>
  </AuthenticatedLayout>
</template>

<script setup>
import { h, onMounted, ref } from 'vue';
import api from '@/utils/api';
import AuthenticatedLayout from '../components/layouts/AuthenticatedLayout.vue';
import NeonButton from '../components/NeonButton.vue';
import TopCard from '../components/ui/TopCard.vue';
import { useUser } from '@/composables/useUser';
const { user } = useUser(); const requests = ref([]); const error = ref(''); const loading = ref(false); const saving = ref(false); const modal = ref(false); const decisionModal = ref(false); const rulesModal = ref(false); const rules = ref([]); const profiles = ref([]); const ruleForm = ref({ profile_id: '', approval_order: 1, minimum_amount: 0, maximum_amount: null }); const selected = ref(null); const decision = ref('approved'); const justification = ref(''); const form = ref({ title: '', description: '', amount: null, due_date: '' });
const ReceiptIcon = { render: () => h('span', { class: 'text-cyan-300' }, 'R$') }; const money = (value) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value || 0)); const status = (value) => ({ draft: 'Rascunho', submitted: 'Enviada', in_approval: 'Em aprovação', approved: 'Aprovada', rejected: 'Recusada', converted: 'Despesa criada' }[value] || value);
const canSubmit = (item) => ['draft', 'rejected'].includes(item.status) && item.requested_by === user.value?.id;
async function load() { loading.value = true; try { requests.value = (await api.get('/finance/expense-requests')).data; } catch (requestError) { error.value = 'Não foi possível carregar as solicitações.'; } finally { loading.value = false; } }
function openCreate() { form.value = { title: '', description: '', amount: null, due_date: '' }; modal.value = true; }
async function openRules() { try { const [rulesResponse, profilesResponse] = await Promise.all([api.get('/finance/expense-approval-rules'), api.get('/profiles')]); rules.value = rulesResponse.data; profiles.value = profilesResponse.data.data || profilesResponse.data; ruleForm.value = { profile_id: '', approval_order: (rules.value.at(-1)?.approval_order || 0) + 1, minimum_amount: 0, maximum_amount: null }; rulesModal.value = true; } catch { error.value = 'Não foi possível carregar as regras de aprovação.'; } }
async function saveRule() { try { await api.post('/finance/expense-approval-rules', { ...ruleForm.value, maximum_amount: ruleForm.value.maximum_amount || null }); await openRules(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível salvar a regra.'; } }
async function removeRule(rule) { try { await api.delete(`/finance/expense-approval-rules/${rule.id}`); rules.value = rules.value.filter((item) => item.id !== rule.id); } catch { error.value = 'Não foi possível remover a regra.'; } }
async function save() { saving.value = true; try { await api.post('/finance/expense-requests', form.value); modal.value = false; await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível salvar a solicitação.'; } finally { saving.value = false; } }
async function submit(item) { try { await api.post(`/finance/expense-requests/${item.id}/submit`); await load(); } catch (requestError) { error.value = requestError.response?.data?.message || Object.values(requestError.response?.data?.errors || {}).flat().join(' ') || 'Não foi possível enviar.'; } }
function openDecision(item, value) { selected.value = item; decision.value = value; justification.value = ''; decisionModal.value = true; }
async function decide() { try { await api.post(`/finance/expense-requests/${selected.value.id}/decision`, { decision: decision.value, justification: justification.value }); decisionModal.value = false; await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível registrar a decisão.'; } }
async function convert(item) { try { await api.post(`/finance/expense-requests/${item.id}/convert-to-payable`); await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Selecione uma conta financeira antes de criar a despesa.'; } }
onMounted(load);
</script>
<style scoped>.input { width: 100%; border: 1px solid rgb(75 85 99); border-radius: .5rem; background: rgb(31 41 55); color: white; padding: .65rem .75rem; }</style>
